void Solver::bump_var(int var, double coeff) {
    // Use a non-linear bump: variables at higher decision levels get a stronger boost
    // This helps focus attention on variables involved in recent, high-level conflicts
    double level_boost = 1.0;
    if (level[var] > 0) {
        // Scale boost by log of decision level to favor recently active variables
        int lv = level[var];
        if (lv > 1) {
            // Apply a mild logarithmic boost based on decision level
            level_boost = 1.0 + 0.1 * (lv > 10 ? 10 : lv) / 10.0;
        }
    }
    if ((activity[var] += var_inc * coeff * level_boost) > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
